#!/usr/bin/env python3
"""Collect the pinned packages' notices for source and binary distribution."""
import json
import subprocess
import sys
from pathlib import Path

checkouts = {path.name.lower(): path for path in Path('.build/checkouts').iterdir()}
checkouts['swiftmail'] = Path('.build/upstream/SwiftMail.git')
pins = json.loads(Path('Package.resolved').read_text())['pins']
pins.append(json.loads(Path('vendor/SwiftMail/upstream.json').read_text()))
parts = ['Third-party notices for MailSearch\n\n'
         'Generated by script/licences.py from Package.resolved and vendor/SwiftMail/upstream.json.\n'
         'Dependencies retain their own licences, reproduced below.\n'
         'SwiftMail uses the transport patch in vendor/SwiftMail and extensions in script/support.\n'
         'SwiftNIO IMAP is patched by script/support.\n']
for pin in sorted(pins, key=lambda pin: pin['identity']):
    checkout = checkouts[pin['identity']]
    revision = pin['state']['revision']
    if pin['identity'] != 'swiftmail':
        assert subprocess.check_output(
            ['git', '-C', str(checkout), 'rev-parse', 'HEAD'], text=True
        ).strip() == revision, f'Resolve pinned packages first: {checkout}'
    files = subprocess.check_output(
        ['git', '-C', str(checkout), 'ls-tree', '-r', '--name-only', revision], text=True
    ).splitlines()
    notices = [name for name in files if Path(name).name.upper().startswith(('LICENSE', 'NOTICE', 'COPYING'))]
    assert notices, f'Missing licence: {checkout}'
    parts.append(f"\n{'=' * 72}\n{pin['identity']} {pin['state']['version']}\n"
                 f"{pin['location']}\nRevision: {revision}\n")
    for name in notices:
        parts.append(f'\n--- {name} ---\n\n' + subprocess.check_output(
            ['git', '-C', str(checkout), 'show', f'{revision}:{name}'], text=True
        ))

output = '\n'.join(parts)
target = Path('THIRD-PARTY-NOTICES.txt')
if sys.argv[1:] == ['--write']:
    target.write_text(output)
elif not target.exists() or target.read_text() != output:
    sys.exit('Third-party notices are stale. Run python3 script/licences.py --write.')
